class Card:
    def __init__(self, name, pair_id):
        self.name = name
        self.pair_id = pair_id
        self.face_up = False
        self.matched = False

    def reveal(self):
        if self.face_up or self.matched:
            return False
        self.face_up = True
        return True

def __init__(self, sample=False):
    pairs = SAMPLE.copy()
    if not sample:
        shuffle(pairs)
    self.cards = [Card(f'C{i+1:02}', pair)
                  for i, pair in enumerate(pairs)]

def queue(self, name):
    if self.phase not in ('first', 'second') or self.pending:
        return False
    card = self.board.get(name)
    if card is None or card.face_up or card.matched:
        return False
    self.pending = card
    return True

def step(self):
    if self.pending and self.phase in ('first', 'second'):
        card = self.pending
        self.pending = None
        card.reveal()
        if self.phase == 'first':
            self.first = card
            self.phase = 'second'
        else:
            self.second = card
            self.phase = 'compare'
        return True

def compare(self):
    if self.phase != 'compare' or not (self.first and self.second):
        return
    self.result = self.first.pair_id == self.second.pair_id
    self.turns += 1
    self.phase = 'resolve'

def settle(self):
    if self.phase != 'resolve' or not (self.first and self.second):
        return
    if self.result:
        self.first.mark_matched()
        self.second.mark_matched()
        self.matches += 1
    else:
        self.first.hide()
        self.second.hide()
    self.first = self.second = None
    self.result = None
    self.phase = 'won' if self.board.complete else 'first'

